SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
DECLARE v_n NUMBER;v_total NUMBER;BEGIN
 SELECT COUNT(DISTINCT TO_CHAR(FECHA_HORA_TRANSACCION,'YYYYMM')) INTO v_n FROM HECHOS_VENTAS WHERE FECHA_HORA_TRANSACCION>=TIMESTAMP '2026-01-01 00:00:00' AND FECHA_HORA_TRANSACCION<TIMESTAMP '2026-10-01 00:00:00';
 IF v_n<>9 THEN RAISE_APPLICATION_ERROR(-20110,'Faltan meses enero-septiembre');END IF;
 SELECT COUNT(DISTINCT CODIGO_TRANSACCION),SUM(TOTAL_LINEA_USD) INTO v_n,v_total FROM HECHOS_VENTAS WHERE FECHA_HORA_TRANSACCION>=TIMESTAMP '2026-09-01 00:00:00' AND FECHA_HORA_TRANSACCION<TIMESTAMP '2026-10-01 00:00:00';
 IF v_n<>147 OR v_total<>302542.27 THEN RAISE_APPLICATION_ERROR(-20111,'Septiembre no coincide con la base recibida'); END IF;
 SELECT COUNT(DISTINCT CODIGO_TRANSACCION),SUM(TOTAL_LINEA_USD) INTO v_n,v_total FROM HECHOS_VENTAS WHERE TO_CHAR(FECHA_HORA_TRANSACCION,'YYYYMM')='202601' AND ID_TRANSACCION_OLTP BETWEEN 200001 AND 200986;
 IF v_n<>92 OR v_total<>172157.12 THEN RAISE_APPLICATION_ERROR(-20112,'Diferencia en lote 202601'); END IF;
 SELECT COUNT(DISTINCT CODIGO_TRANSACCION),SUM(TOTAL_LINEA_USD) INTO v_n,v_total FROM HECHOS_VENTAS WHERE TO_CHAR(FECHA_HORA_TRANSACCION,'YYYYMM')='202602' AND ID_TRANSACCION_OLTP BETWEEN 200001 AND 200986;
