 IF v_n<>125 OR v_total<>257695.57 THEN RAISE_APPLICATION_ERROR(-20112,'Diferencia en lote 202606'); END IF;
 SELECT COUNT(DISTINCT CODIGO_TRANSACCION),SUM(TOTAL_LINEA_USD) INTO v_n,v_total FROM HECHOS_VENTAS WHERE TO_CHAR(FECHA_HORA_TRANSACCION,'YYYYMM')='202607' AND ID_TRANSACCION_OLTP BETWEEN 200001 AND 200986;
 IF v_n<>145 OR v_total<>287328.90 THEN RAISE_APPLICATION_ERROR(-20112,'Diferencia en lote 202607'); END IF;
 SELECT COUNT(DISTINCT CODIGO_TRANSACCION),SUM(TOTAL_LINEA_USD) INTO v_n,v_total FROM HECHOS_VENTAS WHERE TO_CHAR(FECHA_HORA_TRANSACCION,'YYYYMM')='202608' AND ID_TRANSACCION_OLTP BETWEEN 200001 AND 200986;
